import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = List.of(1, 2, 3, 4);
        List<Integer> bp = nums.stream()
            .map(x -> x * x)
            .collect(Collectors.toList());
        System.out.println(bp);
    }
}
